"use client";

import { useEffect, useState } from "react";
import { prefersReducedMotion } from "@/lib/gsap";

export default function PageLoader() {
  const [ready, setReady] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const startedAt = performance.now();
    const minimumDuration = prefersReducedMotion() ? 0 : 700;

    const nextFrame = () =>
      new Promise<void>((resolve) => {
        requestAnimationFrame(() => requestAnimationFrame(() => resolve()));
      });

    const preparePage = async () => {
      if (document.fonts?.ready) {
        await document.fonts.ready;
      }
      await nextFrame();

      const remaining = Math.max(0, minimumDuration - (performance.now() - startedAt));
      if (remaining > 0) {
        await new Promise((resolve) => window.setTimeout(resolve, remaining));
      }

      if (!cancelled) {
        document.documentElement.classList.add("page-ready");
        setReady(true);
      }
    };

    preparePage();
    return () => {
      cancelled = true;
      document.documentElement.classList.remove("page-ready");
    };
  }, []);

  return (
    <div
      aria-hidden={ready}
      className={`page-loader ${ready ? "is-ready" : ""}`}
    >
      <span aria-hidden className="page-loader-panel page-loader-panel-top" />
      <span aria-hidden className="page-loader-panel page-loader-panel-bottom" />
      <div className="page-loader-mark">
        <span>LC</span>
      </div>
      <div className="page-loader-line">
        <span />
      </div>
    </div>
  );
}
